// TypeScript example - streaming resume token helper
import { RedwoodClient } from '@redwood/sdk'
const client = new RedwoodClient({ apiKey: process.env.REDWOOD_KEY, retryPolicy: { maxRetries: 1, baseDelayMs: 100 } })
const stream = await client.generate({ prompt: 'write a summary' })
stream.on('data', chunk => {
  if (chunk.resumeToken) {
    // persist token to resume if connection drops
    localStorage.setItem('resumeToken', chunk.resumeToken)
  }
})
// resume later: client.resumeGenerate({ resumeToken: localStorage.getItem('resumeToken') })

